 try{await new Promise<void>((done,reject)=>{let output='',errors='';const timer=setTimeout(()=>reject(Error('DuckDB crash worker timeout')),20000);child.stdout.on('data',b=>{output+=b;const match=/READY (\d+)/.exec(output);if(match){completed=Number(match[1]);clearTimeout(timer);done()}});child.stderr.on('data',b=>errors=(errors+b).slice(-2000));child.once('error',e=>{clearTimeout(timer);reject(e)});child.once('exit',code=>{clearTimeout(timer);reject(Error('Early DuckDB worker exit '+code+': '+errors))})})}finally{if(child.exitCode===null&&child.signalCode===null)child.kill('SIGKILL');await closed}
